class Solution:
    def sumOfProductBlocks(self, m: int) -> int:
        MOD = 1_000_000_007
        total_sum = 0
        cur = 1
        for k in range(1, m + 1):
            block_prod = 1
            for _ in range(k):
                block_prod = (block_prod * cur) % MOD
                cur += 1
            total_sum = (total_sum + block_prod) % MOD
        return total_sum

class Solution {
public:
    int sumOfProductBlocks(int m) {
        const int MOD = 1000000007;
        long long total_sum = 0;
        long long cur = 1;
        for (int k = 1; k <= m; k++) {
            long long block_prod = 1;
            for (int i = 0; i < k; i++) {
                block_prod = (block_prod * cur) % MOD;
                cur++;
            }
            total_sum = (total_sum + block_prod) % MOD;
        }
        return total_sum;
    }
};

