var sumOfProductBlocks = function(m) {
    const MOD = 1000000007;
    let totalSum = 0;
    let cur = 1;
    for (let k = 1; k <= m; k++) {
        let blockProd = 1;
        for (let i = 0; i < k; i++) {
            blockProd = Number((BigInt(blockProd) * BigInt(cur)) % BigInt(MOD));
